const std=@import("std");const builtin=@import("builtin");fn path(b:*std.Build,n:[]const u8)std.Build.LazyPath{return .{.cwd_relative=b.pathFromRoot(n)};}pub fn build(b:*std.Build)void{if(!std.mem.eql(u8,builtin.zig_version_string,"0.16.0"))@panic("Use Zig 0.16.0");const target=b.standardTargetOptions(.{});const optimize=b.standardOptimizeOption(.{});const odin=b.option([]const u8,"odin-object","Pinned Odin object") orelse "../competition/odin-out/competitive.o";const z=b.addLibrary(.{.name="portable-zig",.linkage=.static,.root_module=b.createModule(.{.root_source_file=path(b,"../src/root.zig"),.target=target,.optimize=optimize,.link_libc=true})});z.bundle_compiler_rt=true;const e=b.addExecutable(.{.name="portable-probe",.root_module=b.createModule(.{.target=target,.optimize=optimize,.link_libc=true})});for([_][]const u8{"../src","../conformance","../platform"})|i|e.root_module.addIncludePath(path(b,i));const f=&.{"-std=c11","-Wall","-Wextra","-Werror","-UNDEBUG","-ffp-contract=off"};for([_][]const u8{"../src/backends.c","../src/competitive.c","../conformance/conformance.c","../platform/dynlib.c","probe.c"})|s|e.root_module.addCSourceFile(.{.file=path(b,s),.flags=f});e.root_module.addObjectFile(path(b,odin));e.root_module.linkLibrary(z);if(target.result.os.tag==.linux)e.root_module.linkSystemLibrary("dl",.{});const r=b.addRunArtifact(e);r.has_side_effects=true;const t=b.step("test","Execute C/Zig/Odin ABI and semantic conformance");t.dependOn(&r.step);b.installArtifact(e);b.default_step=t;}
